/*
 * Example demonstrating how to retrieve a device ID (using stat(2)) 
 * and then pass it to the deprecated ustat(2) syscall.
 */
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <unistd.h>
#include <errno.h>

// Defining struct ustat since <ustat.h> may be missing on modern systems
struct ustat {
    long f_tfree;      /* Total free blocks (using long as placeholder for daddr_t) */
    long f_tinode;     /* Number of free inodes (using long as placeholder for ino_t) */
    char f_fname[6];
    char f_fpack[6];
};

// Note: On systems where ustat(2) is fully removed, this code will fail to link 
// unless a compatibility library is used or the syscall is directly invoked.
// We simulate the call here.
extern int ustat(dev_t dev, struct ustat *ubuf);

int main(int argc, char *argv[]) {
    struct stat st;
    struct ustat ubuf;
    const char *path = (argc > 1) ? argv[1] : "/"; 
    dev_t fs_dev;

    // 1. Get the device ID for the target filesystem (e.g., the root FS)
    if (stat(path, &st) == -1) {
        perror("stat failed on path");
        return EXIT_FAILURE;
    }
    fs_dev = st.st_dev;

    printf("Target path: %s (Device ID: %lu)\n", path, (unsigned long)fs_dev);

    // 2. Call ustat()
    if (ustat(fs_dev, &ubuf) == 0) {
        printf("\nUSTAT Success:\n");
        printf("  Total free blocks: %ld\n", ubuf.f_tfree);
        printf("  Free inodes: %ld\n", ubuf.f_tinode);
    } else {
        if (errno == ENOSYS) {
             fprintf(stderr, "\nError: ustat() failed. Syscall often unsupported (ENOSYS) or deprecated. Use statfs(2).\n");
        } else {
             perror("ustat failed");
        }
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
